const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rs=n=>'Rs '+Number(n||0).toLocaleString('en-PK',{maximumFractionDigits:2});
const date=s=>s?new Date(String(s).replace(' ','T')).toLocaleDateString('en-PK',{day:'2-digit',month:'short',year:'numeric'}):'—';
const warrantyEnd=(start,days)=>{if(!days)return '—';const d=new Date(String(start).replace(' ','T'));d.setDate(d.getDate()+Number(days));return date(d.toISOString())};
const badge=(s)=>{const t=String(s||'');return `<span class="badge ${/available|completed|ready|resolved|approved|paid/i.test(t)?'green':/pending|checking|waiting|received|open/i.test(t)?'amber':/sold|rejected|overdue/i.test(t)?'red':'gray'}">${esc(t)}</span>`};
const fmtErr=e=>e?.message||'Something went wrong';
let token=localStorage.getItem('shop_token')||'',user=null,page='dashboard',modalClose=null,cache={};
const nav=[['dashboard','◫','Overview'],['pos','▣','Point of sale'],['inventory','▦','Inventory'],['purchases','⇥','Purchases'],['sales','◧','Sales & invoices'],['contacts','♙','Customers & suppliers'],['repairs','⚒','Repair workshop'],['warranties','◇','Warranty claims'],['installments','▤','Installments'],['cash','◉','Cash & expenses'],['reports','▥','Reports'],['rates','↗','Market rates'],['search','⌕','IMEI & search'],['settings','⚙','Settings']];
async function api(path,method='GET',data){const r=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json',...(token?{'Authorization':'Bearer '+token}:{})},body:data===undefined?undefined:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j;}
function toast(message,error=false){document.querySelector('.toast')?.remove();const div=document.createElement('div');div.className='toast'+(error?' error':'');div.textContent=message;document.body.append(div);setTimeout(()=>div.remove(),4200)}
async function boot(){try{const st=await api('/status');if(st.setup)return login(true);if(token){user=await api('/me');return render()}login(false)}catch(e){toast(fmtErr(e),true)}}
function login(setup){$('#app').innerHTML=`<div class="login-bg"><form class="login-card" id="auth-form"><div class="brand-icon">▣</div><h1>${setup?'Set up your shop':'Welcome back'}</h1><p>${setup?'Create the owner account to start managing your shop.':'Sign in to your shop workspace.'}</p>${setup?`<div class="field"><label>Your name</label><input name="name" required autocomplete="name"></div>`:''}<div class="field"><label>Username</label><input name="username" required autocomplete="username"></div><div class="field"><label>Password</label><input type="password" name="password" required minlength="8" autocomplete="${setup?'new-password':'current-password'}"></div><button class="btn primary" type="submit">${setup?'Create owner account':'Sign in'} →</button><div class="helpbox">Local first • Your shop data is stored on this computer. Make a backup regularly from Settings.</div></form></div>`;$('#auth-form').onsubmit=async ev=>{ev.preventDefault();try{const d=Object.fromEntries(new FormData(ev.target));if(setup){await api('/setup','POST',d);toast('Owner account created');login(false)}else{const r=await api('/login','POST',d);token=r.token;localStorage.setItem('shop_token',token);user=r.user;page='dashboard';render()}}catch(e){toast(fmtErr(e),true)}}}
function shell(){const groups=[['WORKSPACE',nav.slice(0,2)],['MANAGEMENT',nav.slice(2,10)],['INSIGHTS',nav.slice(10)]];return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-icon">▣</div><span>Mobile Shop<small>ERP SYSTEM</small></span></div>${groups.map(([label,items])=>`<div class="side-label">${label}</div>${items.filter(([key])=>!(key==='purchases'&&!roleAtLeast('manager'))&&!(key==='reports'&&!roleAtLeast('manager'))&&!(key==='cash'&&!roleAtLeast('cashier'))&&!(key==='pos'&&!roleAtLeast('salesman'))).map(([key,icon,name])=>`<button class="nav ${page===key?'active':''}" data-page="${key}" title="${esc(name)}"><span class="ico">${icon}</span><span class="txt">${name}</span></button>`).join('')}`).join('')}<div class="side-bottom"><div class="side-user"><div class="avatar">${esc(user.name[0]?.toUpperCase())}</div><div><strong>${esc(user.name)}</strong><small>${esc(user.role)}</small></div></div><button class="logout" data-action="logout">Sign out</button></div></aside><div class="main"><header class="topbar"><div><span class="crumb">Workspace / </span><strong>${esc(nav.find(n=>n[0]===page)?.[2]||'Overview')}</strong></div><div class="top-actions"><input class="top-search" id="global-search" placeholder="Search IMEI, customer, invoice..."><span class="pill">● &nbsp; Local system</span></div></header><main class="content" id="content"></main></div></div>`}
async function render(){if(!user)return;$('#app').innerHTML=shell();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});$('#global-search').onkeydown=e=>{if(e.key==='Enter'){page='search';window.searchTerm=e.target.value;render()}};document.querySelector('[data-action="logout"]').onclick=async()=>{try{await api('/logout','POST',{token})}catch{}token='';user=null;localStorage.removeItem('shop_token');login(false)};const content=$('#content');content.innerHTML='<div class="empty">Loading...</div>';try{await pages[page]()}catch(e){content.innerHTML=`<div class="alert">${esc(fmtErr(e))}</div>`;toast(fmtErr(e),true)}}
const heading=(eyebrow,title,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
const empty=(label='Nothing here yet',desc='Add your first record to get started.')=>`<div class="empty"><div class="big">▦</div><strong>${label}</strong>${desc}</div>`;
function table(headers,rows){return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}">${empty()}</td></tr>`}</tbody></table></div>`}
function modal(title,html,onSubmit,{wide=false,save='Save'}={}){closeModal();const layer=document.createElement('div');layer.className='modal-overlay';layer.innerHTML=`<div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><div class="modal-head"><h2>${esc(title)}</h2><button class="close" type="button">×</button></div><form id="modal-form"><div class="modal-body">${html}</div><div class="modal-foot"><button type="button" class="btn cancel">Cancel</button><button type="submit" class="btn primary">${esc(save)}</button></div></form></div>`;document.body.append(layer);const close=()=>layer.remove();modalClose=close;layer.querySelector('.close').onclick=close;layer.querySelector('.cancel').onclick=close;layer.onclick=e=>{if(e.target===layer)close()};layer.querySelector('form').onsubmit=async e=>{e.preventDefault();const btn=layer.querySelector('[type=submit]');btn.disabled=true;try{await onSubmit(e.target);close();render()}catch(err){toast(fmtErr(err),true)}finally{btn.disabled=false}};setTimeout(()=>layer.querySelector('input,select,textarea')?.focus(),20);return layer}
function closeModal(){modalClose?.();modalClose=null}
const field=(label,name,type='text',value='',opts={})=>`<div class="field ${opts.full?'full':''}"><label>${esc(label)}</label><input name="${name}" type="${type}" value="${esc(value)}" ${opts.required?'required':''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.step?`step="${opts.step}"`:''} placeholder="${esc(opts.placeholder||'')}"></div>`;
const select=(label,name,options,value='',full=false)=>`<div class="field ${full?'full':''}"><label>${esc(label)}</label><select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;
const textArea=(label,name,value='',full=true)=>`<div class="field ${full?'full':''}"><label>${esc(label)}</label><textarea name="${name}">${esc(value)}</textarea></div>`;
const fd=form=>Object.fromEntries(new FormData(form));
const contactOpts=(contacts,kind)=>[['','Select '+kind],...contacts.filter(c=>c.kind===kind).map(c=>[c.id,c.name+(c.phone?' · '+c.phone:'')])];
const productOpts=(products,filter)=>[['','Select item'],...products.filter(filter).map(p=>[p.id,p.name+(p.sku?' · '+p.sku:'')])];
const methods=[['cash','Cash'],['bank','Bank transfer'],['card','Card'],['easypaisa','EasyPaisa'],['jazzcash','JazzCash']];
const categoryOpts=[['phone','Mobile phone'],['charger','Charger'],['cable','Cable'],['handsfree','Handsfree'],['cover','Cover'],['glass','Screen glass / protector'],['power_bank','Power bank'],['smart_watch','Smart watch'],['memory_card','Memory card'],['spare_part','Spare part'],['other','Other accessory']];
const checks=['Screen','Touch','Camera','Mic','Speaker','Charging','Network','Wi-Fi','Bluetooth','Battery','Biometrics'];
const checklistHtml=prefix=>`<div class="field full"><label>Used phone testing checklist</label><div class="check-grid">${checks.map(k=>`<label><input type="checkbox" name="${prefix}_${k.toLowerCase().replace(/[^a-z]/g,'')}"> ${k} passed</label>`).join('')}</div></div>`;
const checklistData=(d,prefix)=>Object.fromEntries(checks.map(k=>[k,!!d[`${prefix}_${k.toLowerCase().replace(/[^a-z]/g,'')}`]]));
const roleAtLeast=r=>({technician:1,salesman:2,cashier:3,manager:4,owner:5}[user.role]||0)>=({technician:1,salesman:2,cashier:3,manager:4,owner:5}[r]||0);
async function dashboard(){const d=await api('/dashboard');$('#content').innerHTML=heading('Your shop at a glance','Good '+(new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening')+', '+esc(user.name.split(' ')[0]),'Here is what is happening across your shop today.',`<button class="btn" id="new-purchase">＋ Purchase stock</button><button class="btn primary" id="new-sale">＋ New sale</button>`)+`<div class="grid4"><div class="stat"><div class="label">Today’s sales</div><div class="symbol">↗</div><div class="value">${rs(d.salesToday)}</div><div class="hint">Total invoiced today</div></div><div class="stat"><div class="label">This month</div><div class="symbol">▤</div><div class="value">${rs(d.salesMonth)}</div><div class="hint">Monthly revenue</div></div><div class="stat"><div class="label">Customer balances</div><div class="symbol">◷</div><div class="value">${rs(d.outstanding)}</div><div class="hint">Outstanding on sales</div></div><div class="stat"><div class="label">Phones in stock</div><div class="symbol">▣</div><div class="value">${d.availablePhones}</div><div class="hint">IMEI tracked units</div></div></div><div class="grid2 section"><div class="panel"><div class="panel-head"><h2>Sales · last 7 days</h2><span class="subtle">Daily revenue</span></div>${chart(d.chart)}</div><div class="panel"><div class="panel-head"><h2>Needs attention</h2><span class="subtle">Stock & workshop</span></div><div class="summary-box"><span>Repairs ready for pickup</span><strong>${d.repairsReady}</strong></div><div class="summary-box"><span>Overdue installments</span><strong>${d.overdue}</strong></div><div class="summary-box"><span>Low stock items</span><strong>${d.lowStock.length}</strong></div></div></div><div class="grid2 section"><div class="panel"><div class="panel-head"><h2>Recent sales</h2><button class="btn small" data-goto="sales">View all →</button></div>${table(['Invoice','Customer','Amount','Balance'],d.recentSales.map(s=>`<tr><td class="main-cell">${esc(s.invoice_no)}</td><td>${esc(s.customer||'Walk-in')}</td><td>${rs(s.total)}</td><td>${rs(s.total-s.paid)}</td></tr>`))}</div><div class="panel"><div class="panel-head"><h2>Low stock alerts</h2><button class="btn small" data-goto="inventory">View stock →</button></div>${d.lowStock.length?table(['Item','In stock','Reorder at'],d.lowStock.map(p=>`<tr><td class="main-cell">${esc(p.name)}</td><td>${badge(p.quantity+' left')}</td><td>${p.reorder_level}</td></tr>`)):empty('All stocked up','No items are below their reorder level.')}</div></div>`;$('#new-purchase').onclick=()=>purchaseModal();$('#new-sale').onclick=()=>saleModal();document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{page=b.dataset.goto;render()})}
function chart(rows){const max=Math.max(1,...rows.map(r=>r.total));const map=new Map(rows.map(r=>[r.day,r.total]));return `<div class="chart">${Array.from({length:7},(_,i)=>{const day=new Date(Date.now()-(6-i)*86400000).toISOString().slice(0,10),v=map.get(day)||0;return `<div class="chart-col"><div class="chart-bar" title="${rs(v)}" style="height:${Math.max(3,v/max*130)}px"></div><span>${new Date(day).toLocaleDateString('en-PK',{weekday:'short'})}</span></div>`}).join('')}</div>`}
async function inventory(){const [products,phones]=await Promise.all([api('/products'),api('/phones')]);cache.products=products;cache.phones=phones;let tab='all',query='';const draw=()=>{const filtered=products.filter(p=>(tab==='all'||(tab==='phones'?p.category==='phone':tab==='accessories'?p.category!=='phone'&&p.category!=='spare_part':p.category==='spare_part'))&&(p.name+' '+p.sku+' '+p.brand+' '+p.model).toLowerCase().includes(query));$('#inventory-table').innerHTML=table(['Product','Category','SKU / barcode','Stock','Cost','Sale price',''],filtered.map(p=>`<tr><td class="main-cell">${esc(p.name)}<div class="subtle">${esc([p.brand,p.model,p.variant,p.color,p.storage].filter(Boolean).join(' · '))}</div></td><td>${esc(categoryOpts.find(x=>x[0]===p.category)?.[1]||p.category)}</td><td class="muted">${esc(p.sku||p.barcode||'—')}</td><td>${p.category==='phone'?badge((p.phone_quantity||0)+' units'):badge(p.quantity+' units')}</td><td>${roleAtLeast('manager')?rs(p.cost):'—'}</td><td>${rs(p.price)}</td><td><div class="actions">${roleAtLeast('manager')?`<button class="btn small edit-product" data-id="${p.id}">Edit</button>`:''}${p.category!=='phone'?`<button class="btn small label-product" data-id="${p.id}">Label</button>`:''}</div></td></tr>`));document.querySelectorAll('.edit-product').forEach(b=>b.onclick=()=>productModal(products.find(p=>p.id==b.dataset.id)));document.querySelectorAll('.label-product').forEach(b=>b.onclick=()=>labelModal(products.find(p=>p.id==b.dataset.id)))};$('#content').innerHTML=heading('Stock control','Inventory','Track every phone by IMEI and every accessory by quantity.',`${roleAtLeast('manager')?'<button class="btn" id="add-stock">＋ Receive stock</button>':''}${roleAtLeast('manager')?'<button class="btn primary" id="add-product">＋ Add product</button>':''}`)+`<div class="toolbar"><div class="filters">${[['all','All items'],['phones','Phones'],['accessories','Accessories'],['spare_part','Spare parts']].map(([k,t])=>`<button class="chip ${tab===k?'active':''}" data-tab="${k}">${t}</button>`).join('')}</div><input class="search" id="inventory-search" placeholder="Search product, model or SKU"></div><div id="inventory-table"></div><div class="panel section"><div class="panel-head"><h2>Individual phone stock</h2><span class="subtle">IMEI and PTA status</span></div>${table(['IMEI 1','Model','Condition','PTA status','Cost','Stock status'],phones.map(h=>`<tr><td class="main-cell">${esc(h.imei1)}<div class="subtle">${esc(h.imei2||'')}</div></td><td>${esc(h.product_name)}</td><td>${esc(h.condition_grade||'—')}</td><td>${badge(h.pta_status)}</td><td>${roleAtLeast('manager')?rs(h.purchase_cost):'—'}</td><td>${badge(h.status)}</td></tr>`))}</div>`;draw();$('#inventory-search').oninput=e=>{query=e.target.value.toLowerCase();draw()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));draw()});$('#add-stock')?.addEventListener('click',()=>purchaseModal());$('#add-product')?.addEventListener('click',()=>productModal())}
function productModal(existing){modal(existing?'Edit product':'New product',`<div class="form-grid">${field('Product name','name','text',existing?.name||'',{required:true,full:true})}${select('Category','category',categoryOpts,existing?.category||'phone')}${field('SKU','sku','text',existing?.sku||'')}${field('Barcode','barcode','text',existing?.barcode||'')}${field('Brand','brand','text',existing?.brand||'')}${field('Model','model','text',existing?.model||'')}${field('Variant','variant','text',existing?.variant||'')}${field('Color','color','text',existing?.color||'')}${field('Storage','storage','text',existing?.storage||'')}${select('Condition','condition',[['new','New'],['box_pack','Box pack'],['open_box','Open box'],['kit','Kit'],['used','Used']],existing?.condition||'new')}${field('Cost price','cost','number',existing?.cost||0,{min:0,step:'0.01'})}${field('Sale price','price','number',existing?.price||0,{min:0,step:'0.01'})}${field('Minimum sale price','min_price','number',existing?.min_price||0,{min:0,step:'0.01'})}${field('Reorder alert at','reorder_level','number',existing?.reorder_level||0,{min:0})}${field('Warranty days','warranty_days','number',existing?.warranty_days||0,{min:0})}${textArea('Compatible phone models (for covers / glass)','compatible_models',existing?.compatible_models||'')}</div>`,async form=>{const d=fd(form);if(existing){delete d.category;await api('/products/'+existing.id,'PATCH',d);toast('Product updated')}else{await api('/products','POST',d);toast('Product added')}},{wide:true,save:existing?'Save changes':'Add product'})}
function labelModal(p){const code=String(p.barcode||p.sku||`ITEM-${p.id}`);const layer=modal('Print product label',`<div id="label-print" class="product-label"><strong>${esc(p.name)}</strong><div>${rs(p.price)}</div><svg id="label-bars"></svg><small>${esc(code)}</small></div><p class="inline-note">If you need a specific code on the label, edit the product barcode first.</p><button class="btn" type="button" id="print-label">Print label</button>`,async()=>{},{save:'Close'});try{window.JsBarcode(layer.querySelector('#label-bars'),code,{format:'CODE128',height:52,width:1.6,displayValue:false,margin:8})}catch(e){toast('Barcode could not be generated: '+fmtErr(e),true)}layer.querySelector('#print-label').onclick=()=>{const print=document.createElement('div');print.className='print-only';print.innerHTML=layer.querySelector('#label-print').outerHTML;document.body.append(print);window.print();setTimeout(()=>print.remove(),1000)};layer.querySelector('form').onsubmit=e=>{e.preventDefault();closeModal()}}
async function purchases(){const [rows,used]=await Promise.all([api('/purchases'),api('/used-purchases')]);$('#content').innerHTML=heading('Supplier orders','Purchases','Receive handsets and accessories, then track what you owe.',`<button class="btn" id="used-purchase">＋ Buy used phone</button><button class="btn primary" id="new-purchase">＋ New purchase</button>`)+table(['Date','Supplier','Reference','Total','Paid','Due',''],rows.map(p=>`<tr><td>${date(p.date)}</td><td class="main-cell">${esc(p.supplier||'Unassigned')}</td><td>${esc(p.reference||'—')}</td><td>${rs(p.total)}</td><td>${rs(p.paid)}</td><td>${badge(rs(p.total-p.paid))}</td><td><div class="actions">${p.total>p.paid?`<button class="btn small pay-purchase" data-id="${p.id}" data-due="${p.total-p.paid}">Pay</button>`:''}<button class="btn small return-purchase" data-id="${p.id}">Return item</button></div></td></tr>`))+`<div class="panel section"><div class="panel-head"><h2>Used phones bought from customers</h2></div>${table(['Date','Seller','Phone','IMEI','Price','Paid'],used.map(u=>`<tr><td>${date(u.date)}</td><td class="main-cell">${esc(u.seller)}</td><td>${esc(u.product_name)}</td><td>${esc(u.imei1)}</td><td>${rs(u.agreed_price)}</td><td>${rs(u.paid)} ${u.paid<u.agreed_price?`<button class="btn small used-pay" data-id="${u.id}" data-due="${u.agreed_price-u.paid}">Pay balance</button>`:''}</td></tr>`))}</div>`;$('#new-purchase').onclick=()=>purchaseModal();$('#used-purchase').onclick=()=>usedPurchaseModal();document.querySelectorAll('.pay-purchase').forEach(b=>b.onclick=()=>paymentModal({purchase_id:Number(b.dataset.id),due:Number(b.dataset.due)}));document.querySelectorAll('.return-purchase').forEach(b=>b.onclick=()=>purchaseReturnModal(b.dataset.id));document.querySelectorAll('.used-pay').forEach(b=>b.onclick=()=>usedPurchasePayModal(b.dataset.id,b.dataset.due))}
async function purchaseModal(){const [products,contacts]=await Promise.all([api('/products'),api('/contacts')]);const layer=modal('Receive stock',`<div class="form-grid">${select('Supplier','supplier_id',contactOpts(contacts,'supplier'))}${field('Supplier invoice / reference','reference')}${select('Payment method','payment_method',methods)}${field('Paid now (Rs)','paid','number',0,{min:0,step:'0.01'})}${textArea('Notes','notes')}</div><hr class="divider"><h3 class="form-title">Purchase items</h3><div id="purchase-lines"></div><button type="button" class="btn small" id="add-purchase-line">＋ Add item</button><div class="summary-box"><span>Purchase total</span><strong id="purchase-total">Rs 0</strong></div>`,async form=>{const d=fd(form),lines=[];for(const row of layer.querySelectorAll('.purchase-line')){const productId=Number(row.querySelector('.p-product').value);if(!productId)continue;const p=products.find(x=>x.id===productId),cost=Number(row.querySelector('.p-cost').value);if(p.category==='phone'){const imeis=row.querySelector('.p-imeis').value.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{const [imei1,imei2,pta_status,condition_grade]=x.split(',').map(a=>a.trim());return {imei1,imei2,pta_status,condition_grade}});lines.push({product_id:productId,unit_cost:cost,imeis})}else lines.push({product_id:productId,unit_cost:cost,quantity:Number(row.querySelector('.p-qty').value)})}await api('/purchases','POST',{...d,lines});toast('Stock received')},{wide:true,save:'Receive stock'});const add=()=>{const row=document.createElement('div');row.className='purchase-line';row.innerHTML=`<div class="line-item"><select class="p-product" required>${productOpts(products,()=>true).map(([v,t])=>`<option value="${esc(v)}">${esc(t)}</option>`).join('')}</select><input class="p-qty" type="number" min="1" value="1" title="Quantity"><input class="p-cost" type="number" min="0" step="0.01" placeholder="Unit cost" required><button type="button" class="btn small remove">×</button></div><div class="field p-phone-field" style="display:none;margin-bottom:12px"><label>Phone IMEIs · one per line: IMEI 1, IMEI 2, PTA status, grade</label><textarea class="p-imeis" placeholder="352099001234567, 352099001234568, verified, A"></textarea></div>`;layer.querySelector('#purchase-lines').append(row);const update=()=>{const p=products.find(x=>x.id==row.querySelector('.p-product').value);const isPhone=p?.category==='phone';row.querySelector('.p-phone-field').style.display=isPhone?'flex':'none';row.querySelector('.p-qty').style.display=isPhone?'none':'';row.querySelector('.p-cost').value=p?.cost||'';calc()};row.querySelector('.p-product').onchange=update;row.querySelector('.p-qty').oninput=calc;row.querySelector('.p-cost').oninput=calc;row.querySelector('.p-imeis').oninput=calc;row.querySelector('.remove').onclick=()=>{row.remove();calc()};};const calc=()=>{let n=0;layer.querySelectorAll('.purchase-line').forEach(r=>{const p=products.find(x=>x.id==r.querySelector('.p-product').value),qty=p?.category==='phone'?r.querySelector('.p-imeis').value.split('\n').filter(x=>x.trim()).length:Number(r.querySelector('.p-qty').value)||0;n+=qty*(Number(r.querySelector('.p-cost').value)||0)});layer.querySelector('#purchase-total').textContent=rs(n)};layer.querySelector('#add-purchase-line').onclick=add;add()}
async function usedPurchaseModal(){const [products,contacts]=await Promise.all([api('/products'),api('/contacts')]);modal('Buy a used phone',`<div class="form-grid">${select('Seller / customer','customer_id',contactOpts(contacts,'customer'))}${select('Phone model','product_id',productOpts(products,p=>p.category==='phone'))}${field('IMEI 1','imei1','text','',{required:true})}${field('IMEI 2','imei2')}${select('PTA status','pta_status',[['unknown','Unknown'],['verified','Verified'],['non-PTA','Non-PTA'],['pending','Pending']])}${select('Condition grade','condition_grade',[['','Choose grade'],['A','A'],['B','B'],['C','C']])}${field('Agreed purchase price','agreed_price','number','',{required:true,min:0,step:'0.01'})}${field('Paid now','paid','number',0,{min:0,step:'0.01'})}${select('Payment method','method',methods)}${checklistHtml('used')}${textArea('Testing notes','testing_notes')}</div>`,async form=>{const d=fd(form);d.checklist=checklistData(d,'used');await api('/used-purchases','POST',d);toast('Used phone added to stock')},{wide:true,save:'Buy phone'})}
