async function sales(){const rows=await api('/sales');$('#content').innerHTML=heading('Invoices','Sales history','All invoices, payments and outstanding customer balances.',`<button class="btn primary" id="new-sale">＋ New sale</button>`)+table(['Invoice','Date','Customer','Total','Paid','Balance',''],rows.map(s=>`<tr><td class="main-cell">${esc(s.invoice_no)}</td><td>${date(s.date)}</td><td>${esc(s.customer||'Walk-in')}</td><td>${rs(s.total)}</td><td>${rs(s.paid)}</td><td>${s.total>s.paid?badge(rs(s.total-s.paid)):badge('Paid')}</td><td><button class="btn small view-sale" data-id="${s.id}">View</button></td></tr>`));$('#new-sale').onclick=()=>saleModal();document.querySelectorAll('.view-sale').forEach(b=>b.onclick=()=>invoiceModal(b.dataset.id))}
async function pos(){$('#content').innerHTML=heading('Fast checkout','Point of sale','Sell phones by IMEI, scan accessories and split customer payments.',`<button class="btn primary" id="start-sale">＋ Start sale</button>`)+`<div class="grid3"><div class="stat"><div class="label">Phones</div><div class="value">IMEI</div><div class="hint">Select the exact handset</div></div><div class="stat"><div class="label">Accessories</div><div class="value">Barcode</div><div class="hint">Use a scanner or search</div></div><div class="stat"><div class="label">Payment</div><div class="value">Split</div><div class="hint">Cash, bank and wallets</div></div></div><div class="panel section"><div class="panel-head"><h2>Ready to bill</h2></div><p class="muted">Choose “Start sale” to create an invoice. The sale saves the exact IMEI, reduces stock and records payment immediately.</p></div>`;$('#start-sale').onclick=()=>saleModal()}
async function saleModal(){const [products,phones,contacts]=await Promise.all([api('/products'),api('/phones'),api('/contacts')]);const layer=modal('New sale',`<div class="form-grid">${select('Customer','customer_id',contactOpts(contacts,'customer'))}${field('Discount (Rs)','discount','number',0,{min:0,step:'0.01'})}${textArea('Invoice note','notes')}</div><hr class="divider"><h3 class="form-title">Items</h3><input id="scan-code" class="search" style="width:100%;margin-bottom:14px" placeholder="Scan barcode or IMEI, then press Enter"><div id="sale-lines"></div><button type="button" class="btn small" id="add-sale-line">＋ Add item</button><hr class="divider"><h3 class="form-title">Trade-in phone (optional)</h3><div class="form-grid">${select('Old phone model','trade_product_id',productOpts(products,p=>p.category==='phone'))}${field('Trade-in value','trade_in_value','number',0,{min:0,step:'0.01'})}${field('Old phone IMEI 1','trade_imei1')}${field('Old phone IMEI 2','trade_imei2')}${select('Old phone PTA','trade_pta_status',[['unknown','Unknown'],['verified','Verified'],['non-PTA','Non-PTA'],['pending','Pending']])}${select('Condition grade','trade_condition_grade',[['','Choose grade'],['A','A'],['B','B'],['C','C']])}${checklistHtml('trade')}</div><hr class="divider"><h3 class="form-title">Payments</h3><div id="payment-lines"></div><button type="button" class="btn small" id="add-payment-line">＋ Add payment method</button><div class="summary-box"><span>Amount due after discount & trade-in</span><strong id="sale-total">Rs 0</strong></div><p class="inline-note">For credit sales, choose a customer and leave part of the total unpaid. Schedule due dates from the invoice.</p>`,async form=>{const d=fd(form),lines=[],payments=[];for(const r of layer.querySelectorAll('.sale-line')){const product_id=Number(r.querySelector('.s-product').value);if(product_id)lines.push({product_id,phone_id:Number(r.querySelector('.s-phone').value)||undefined,quantity:Number(r.querySelector('.s-qty').value)||1,unit_price:Number(r.querySelector('.s-price').value)})}for(const r of layer.querySelectorAll('.payment-line')){const amount=Number(r.querySelector('.pay-amount').value);if(amount>0)payments.push({method:r.querySelector('.pay-method').value,amount})}const trade=Number(d.trade_in_value)>0?{product_id:Number(d.trade_product_id),imei1:d.trade_imei1,imei2:d.trade_imei2,pta_status:d.trade_pta_status,condition_grade:d.trade_condition_grade,checklist:checklistData(d,'trade')}:undefined;await api('/sales','POST',{customer_id:d.customer_id,discount:d.discount,notes:d.notes,trade_in_value:d.trade_in_value,trade_in:trade,lines,payments});toast('Invoice created')},{wide:true,save:'Complete sale'});const calc=()=>{let t=0;layer.querySelectorAll('.sale-line').forEach(r=>t+=(Number(r.querySelector('.s-price').value)||0)*(Number(r.querySelector('.s-qty').value)||1));layer.querySelector('#sale-total').textContent=rs(Math.max(0,t-(Number(layer.querySelector('[name=discount]').value)||0)-(Number(layer.querySelector('[name=trade_in_value]').value)||0)))};const addLine=()=>{const row=document.createElement('div');row.className='sale-line';row.innerHTML=`<div class="line-item"><select class="s-product" required>${productOpts(products,()=>true).map(([v,t])=>`<option value="${esc(v)}">${esc(t)}</option>`).join('')}</select><input class="s-qty" type="number" min="1" value="1" title="Quantity"><input class="s-price" type="number" min="0" step="0.01" placeholder="Unit price" required><button type="button" class="btn small remove">×</button></div><div class="field" style="display:none;margin-bottom:12px"><label>Exact phone / IMEI</label><select class="s-phone"></select></div>`;layer.querySelector('#sale-lines').append(row);const update=()=>{const p=products.find(x=>x.id==row.querySelector('.s-product').value);row.querySelector('.s-price').value=p?.price??'';const phoneField=row.querySelector('.field');phoneField.style.display=p?.category==='phone'?'flex':'none';row.querySelector('.s-qty').style.display=p?.category==='phone'?'none':'';row.querySelector('.s-phone').innerHTML=phones.filter(h=>h.product_id===p?.id&&h.status==='available').map(h=>`<option value="${h.id}">${esc(h.imei1)} · ${esc(h.pta_status)} · ${esc(h.condition_grade)}</option>`).join('');calc()};row.querySelector('.s-product').onchange=update;row.querySelector('.s-qty').oninput=calc;row.querySelector('.s-price').oninput=calc;row.querySelector('.remove').onclick=()=>{row.remove();calc()}};const addPayment=()=>{const row=document.createElement('div');row.className='payment-line line-item';row.style.gridTemplateColumns='1fr 1fr auto';row.innerHTML=`<select class="pay-method">${methods.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><input class="pay-amount" type="number" min="0" step="0.01" placeholder="Amount"><button type="button" class="btn small remove">×</button>`;layer.querySelector('#payment-lines').append(row);row.querySelector('.remove').onclick=()=>row.remove()};layer.querySelector('#add-sale-line').onclick=addLine;layer.querySelector('#scan-code').onkeydown=e=>{if(e.key!=='Enter')return;e.preventDefault();const code=e.target.value.trim();const h=phones.find(x=>x.imei1===code||x.imei2===code);const p=products.find(x=>x.id===h?.product_id||x.barcode===code||x.sku===code);if(!p){toast('Barcode or IMEI not found',true);return}addLine();const row=[...layer.querySelectorAll('.sale-line')].at(-1);row.querySelector('.s-product').value=p.id;row.querySelector('.s-product').dispatchEvent(new Event('change'));if(h)row.querySelector('.s-phone').value=h.id;e.target.value='';toast('Item added')};layer.querySelector('#add-payment-line').onclick=addPayment;layer.querySelector('[name=discount]').oninput=calc;layer.querySelector('[name=trade_in_value]').oninput=calc;addLine();addPayment()}
async function invoiceModal(id){const s=await api('/sales/'+id);const html=`<div id="invoice-print" class="invoice"><h1>Mobile Shop ERP</h1><p>Invoice <strong>${esc(s.invoice_no)}</strong> · ${date(s.date)}</p><p>Customer: ${esc(s.customer||'Walk-in')} ${esc(s.customer_phone||'')}</p>${table(['Item','IMEI','Qty','Price','Warranty until','Total'],s.lines.map(l=>`<tr><td>${esc(l.description)}</td><td>${esc(l.imei1||'—')}</td><td>${l.quantity}</td><td>${rs(l.unit_price)}</td><td>${warrantyEnd(s.date,l.warranty_days)}</td><td>${rs(l.quantity*l.unit_price)}</td></tr>`))}<p>Subtotal: ${rs(s.subtotal)} · Discount: ${rs(s.discount)} · Trade-in: ${rs(s.trade_in_value)}</p><h2>Total: ${rs(s.total)}</h2><p>Paid: ${rs(s.paid)} · Balance: ${rs(s.total-s.paid)}</p><p>Thank you for shopping with us.</p></div><div class="actions">${s.total>s.paid?`<button type="button" class="btn" id="invoice-pay">Record payment</button>${s.customer_id&&!s.installments.length?'<button type="button" class="btn" id="invoice-schedule">Schedule installments</button>':''}`:''}<button type="button" class="btn" id="invoice-print-btn">Print receipt</button>${s.customer_phone?'<button type="button" class="btn" id="invoice-share">Share by WhatsApp</button>':''}</div>`;const layer=modal('Invoice details',html,async()=>{},{wide:true,save:'Close'});layer.querySelector('#invoice-pay')?.addEventListener('click',()=>{closeModal();paymentModal({sale_id:s.id,due:s.total-s.paid})});layer.querySelector('#invoice-schedule')?.addEventListener('click',()=>{closeModal();scheduleModal(s)});layer.querySelector('#invoice-share')?.addEventListener('click',()=>{const phone=String(s.customer_phone).replace(/\D/g,'').replace(/^0/,'92');const msg=`Invoice ${s.invoice_no} — Total ${rs(s.total)}, Paid ${rs(s.paid)}, Balance ${rs(s.total-s.paid)}.`;window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(msg),'_blank','noopener')});layer.querySelector('#invoice-print-btn').onclick=()=>{const print=document.createElement('div');print.className='print-only';print.innerHTML=layer.querySelector('#invoice-print').outerHTML;document.body.append(print);window.print();setTimeout(()=>print.remove(),1000)};layer.querySelector('form').onsubmit=e=>{e.preventDefault();closeModal()}}
function scheduleModal(s){const due=s.total-s.paid;const layer=modal('Schedule installments',`<p class="inline-note">Balance to schedule: <strong>${rs(due)}</strong>. The installment amounts must add up to this balance.</p><div id="schedule-lines"></div><button type="button" class="btn small" id="add-schedule">＋ Add due date</button>`,async()=>{const entries=[...layer.querySelectorAll('.schedule-line')].map(r=>({due_date:r.querySelector('.due-date').value,amount:Number(r.querySelector('.due-amount').value)}));await api('/sales/'+s.id+'/installments','POST',{entries});toast('Installments scheduled')},{save:'Save schedule'});const add=()=>{const row=document.createElement('div');row.className='schedule-line line-item';row.style.gridTemplateColumns='1fr 1fr auto';row.innerHTML=`<input class="due-date" type="date" required><input class="due-amount" type="number" min="0.01" step="0.01" placeholder="Amount" required><button type="button" class="btn small">×</button>`;layer.querySelector('#schedule-lines').append(row);row.querySelector('button').onclick=()=>row.remove()};layer.querySelector('#add-schedule').onclick=add;add();layer.querySelector('.due-amount').value=due}
function paymentModal(ref){modal('Record payment',`<div class="form-grid">${field('Amount due','due','text',rs(ref.due))}${field('Amount received','amount','number',ref.due,{min:0,step:'0.01',required:true})}${select('Method','method',methods)}${textArea('Note','notes')}</div>`,async form=>{const d=fd(form);delete d.due;await api('/payments','POST',{...ref,...d});toast('Payment recorded')},{save:'Record payment'})}
async function contacts(){const rows=await api('/contacts');let kind='customer';const draw=()=>{$('#contacts-table').innerHTML=table(['Name','Phone','Address','Type',''],rows.filter(c=>c.kind===kind).map(c=>`<tr><td class="main-cell">${esc(c.name)}</td><td>${esc(c.phone||'—')}</td><td>${esc(c.address||'—')}</td><td>${badge(c.kind)}</td><td><button class="btn small ledger-btn" data-id="${c.id}" data-kind="${c.kind}">View ledger</button></td></tr>`));document.querySelectorAll('.ledger-btn').forEach(b=>b.onclick=()=>ledgerModal(b.dataset.id,b.dataset.kind))};$('#content').innerHTML=heading('People & balances','Customers & suppliers','Keep contact details and complete payment history in one place.',`<button class="btn primary" id="add-contact">＋ Add contact</button>`)+`<div class="toolbar"><div class="filters"><button class="chip active" data-kind="customer">Customers</button><button class="chip" data-kind="supplier">Suppliers</button></div></div><div id="contacts-table"></div>`;draw();document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;document.querySelectorAll('[data-kind]').forEach(x=>x.classList.toggle('active',x===b));draw()});$('#add-contact').onclick=()=>contactModal(kind)}
