async function repairs(){const [rows,users]=await Promise.all([api('/repairs'),roleAtLeast('manager')?api('/users'):Promise.resolve([])]);$('#content').innerHTML=heading('Workshop','Repair jobs','Track each handset from intake to delivery, with parts and labor cost.',`<button class="btn primary" id="add-repair">＋ New job card</button>`)+table(['Job','Customer','Device & fault','Technician','Status','Charges',''],rows.map(r=>`<tr><td class="main-cell">${esc(r.job_no)}<div class="subtle">${date(r.date)}</div></td><td>${esc(r.customer||'—')}</td><td>${esc(r.model)}<div class="subtle">${esc(r.fault)}</div></td><td>${esc(r.technician||'Unassigned')}</td><td>${badge(r.status)}</td><td>${rs(r.labor_charge+r.parts_cost)}</td><td><button class="btn small repair-view" data-id="${r.id}">Manage</button></td></tr>`));$('#add-repair').onclick=()=>repairCreate(users);document.querySelectorAll('.repair-view').forEach(b=>b.onclick=()=>repairManage(rows.find(x=>x.id==b.dataset.id),users))}
