async function repairManage(r,users){const products=await api('/products');const layer=modal(r.job_no+' · '+r.model,`<p class="inline-note">Customer: ${esc(r.customer||'—')} · IMEI: ${esc(r.imei||'—')} · Fault: ${esc(r.fault)}</p><div class="form-grid">${select('Status','status',['Received','Checking','Waiting for Part','In Repair','Ready','Delivered'].map(s=>[s,s]),r.status)}${select('Technician','technician_id',[['','Unassigned'],...users.filter(u=>u.role==='technician').map(u=>[u.id,u.name])],r.technician_id||'')}${field('Labor charge','labor_charge','number',r.labor_charge,{min:0,step:'0.01'})}${field('Other cost','other_cost','number',r.other_cost,{min:0,step:'0.01'})}</div><div class="summary-box"><span>Parts cost · ${rs(r.parts_cost)} &nbsp;|&nbsp; Paid · ${rs(r.paid)}</span><strong>${rs(r.labor_charge+r.parts_cost)}</strong></div><hr class="divider"><h3 class="form-title">Consume a spare part</h3><div class="form-grid">${select('Part','part_product',productOpts(products,p=>p.category==='spare_part'))}${field('Quantity','part_quantity','number',1,{min:1})}</div><div class="actions" style="margin-top:13px"><button type="button" class="btn small" id="consume-part">Use part</button><button type="button" class="btn small" id="repair-payment">Record payment</button><button type="button" class="btn small" id="repair-notify">Copy ready message</button></div>`,async form=>{const d=fd(form);await api('/repairs/'+r.id,'PATCH',{status:d.status,technician_id:d.technician_id||null,labor_charge:d.labor_charge,other_cost:d.other_cost});toast('Repair updated')},{wide:true,save:'Save job'});layer.querySelector('#consume-part').onclick=async()=>{try{await api('/repairs/'+r.id+'/parts','POST',{product_id:Number(layer.querySelector('[name=part_product]').value),quantity:Number(layer.querySelector('[name=part_quantity]').value)});toast('Part used and stock reduced');closeModal();render()}catch(e){toast(fmtErr(e),true)}};layer.querySelector('#repair-payment').onclick=()=>{closeModal();paymentModal({repair_id:r.id,due:r.labor_charge+r.parts_cost-r.paid})};layer.querySelector('#repair-notify').onclick=()=>{navigator.clipboard.writeText(`Hello ${r.customer||'customer'}, your ${r.model} repair (${r.job_no}) is ready for pickup. Please contact our shop.`).then(()=>toast('Ready message copied'))}}
async function warranties(){const rows=await api('/warranties');$('#content').innerHTML=heading('After sales','Warranty claims','Record customer issues, actions and resolutions.',`<button class="btn primary" id="add-claim">＋ New claim</button>`)+table(['Date','Invoice','IMEI','Issue','Action','Status',''],rows.map(w=>`<tr><td>${date(w.date)}</td><td class="main-cell">${esc(w.invoice_no||'—')}</td><td>${esc(w.imei1||'—')}</td><td>${esc(w.issue)}</td><td>${esc(w.action||'—')}</td><td>${badge(w.status)}</td><td><button class="btn small claim-edit" data-id="${w.id}">Update</button></td></tr>`));$('#add-claim').onclick=()=>warrantyCreate();document.querySelectorAll('.claim-edit').forEach(b=>b.onclick=()=>claimManage(rows.find(x=>x.id==b.dataset.id)))}
async function warrantyCreate(){const sales=await api('/sales');modal('New warranty claim',`<div class="form-grid">${select('Invoice','sale_id',[['','Choose invoice'],...sales.map(s=>[s.id,s.invoice_no])])}${field('Phone unit ID (optional)','phone_id','number','',{min:1})}${field('Issue','issue','text','',{required:true,full:true})}${textArea('Action taken','action')}${textArea('Result','result')}</div>`,async form=>{const d=fd(form);await api('/warranties','POST',d);toast('Claim recorded')},{save:'Record claim'})}
function claimManage(w){modal('Update warranty claim',`<div class="form-grid">${select('Status','status',[['open','Open'],['approved','Approved'],['rejected','Rejected'],['resolved','Resolved']],w.status)}${textArea('Action taken','action',w.action)}${textArea('Result','result',w.result)}</div>`,async form=>{await api('/warranties/'+w.id,'PATCH',fd(form));toast('Claim updated')})}
async function installments(){const rows=await api('/installments');$('#content').innerHTML=heading('Customer credit','Installments','See due dates and record each collection.',`<button class="btn" id="reminders">Copy due reminders</button>`)+table(['Due date','Invoice','Customer','Scheduled','Paid','Status',''],rows.map(i=>`<tr><td>${date(i.due_date)}</td><td class="main-cell">${esc(i.invoice_no)}</td><td>${esc(i.customer||'—')}<div class="subtle">${esc(i.phone||'')}</div></td><td>${rs(i.amount)}</td><td>${rs(i.paid)}</td><td>${badge(i.paid>=i.amount?'Paid':i.due_date<new Date().toISOString().slice(0,10)?'Overdue':'Pending')}</td><td>${i.paid<i.amount?`<button class="btn small pay-installment" data-id="${i.id}" data-due="${i.amount-i.paid}">Collect</button>`:''}</td></tr>`));document.querySelectorAll('.pay-installment').forEach(b=>b.onclick=()=>installmentPay(b.dataset.id,b.dataset.due));$('#reminders').onclick=()=>{const text=rows.filter(i=>i.paid<i.amount&&i.due_date<=new Date().toISOString().slice(0,10)).map(i=>`Hello ${i.customer||'customer'}, your installment of ${rs(i.amount-i.paid)} for ${i.invoice_no} was due on ${i.due_date}. Please contact our shop. ${i.phone||''}`).join('\n\n');navigator.clipboard.writeText(text||'No reminders due').then(()=>toast('Reminder text copied'))}}
function installmentPay(id,due){modal('Collect installment',`<div class="form-grid">${field('Amount due','due','text',rs(due))}${field('Amount received','amount','number',due,{required:true,min:0,step:'0.01'})}${select('Method','method',methods)}</div>`,async form=>{const d=fd(form);await api('/installments/'+id+'/pay','POST',{amount:d.amount,method:d.method});toast('Installment collected')},{save:'Collect payment'})}
async function cash(){const [expenses,sessions]=await Promise.all([api('/expenses'),api('/cash')]);const open=sessions.find(s=>!s.closed_at);$('#content').innerHTML=heading('Money management','Cash & expenses','Balance the drawer, record costs and keep owner drawings separate.',`${roleAtLeast('owner')?'<button class="btn" id="owner-draw">Owner drawing</button>':''}<button class="btn primary" id="add-expense">＋ New expense</button>`)+`<div class="grid3"><div class="stat"><div class="label">Cash session</div><div class="value" style="font-size:23px">${open?'Open':'Closed'}</div><div class="hint">${open?'Started '+date(open.opened_at):'Open a new session to count cash'}</div></div><div class="stat"><div class="label">Opening cash</div><div class="value">${rs(open?.opening||0)}</div></div><div class="stat"><div class="label">Expenses today</div><div class="value">${rs(expenses.filter(e=>e.date.slice(0,10)===new Date().toISOString().slice(0,10)).reduce((n,e)=>n+e.amount,0))}</div></div></div><div class="section"><button class="btn" id="cash-action">${open?'Close cash session':'Open cash session'}</button></div><div class="panel section"><div class="panel-head"><h2>Recent expenses</h2></div>${table(['Date','Category','Description','Method','Amount'],expenses.map(e=>`<tr><td>${date(e.date)}</td><td class="main-cell">${esc(e.category)}</td><td>${esc(e.description||'—')}</td><td>${esc(e.method)}</td><td>${rs(e.amount)}</td></tr>`))}</div>`;$('#add-expense').onclick=expenseModal;$('#cash-action').onclick=()=>cashModal(open);$('#owner-draw')?.addEventListener('click',drawModal)}
function expenseModal(){modal('New expense',`<div class="form-grid">${select('Category','category',['Rent','Electricity','Internet','Tea','Transport','Repair tools','Salaries','Other'].map(x=>[x,x]))}${field('Amount','amount','number','',{min:0,step:'0.01',required:true})}${select('Payment method','method',methods)}${field('Description','description')}</div>`,async form=>{await api('/expenses','POST',fd(form));toast('Expense recorded')},{save:'Record expense'})}
function cashModal(open){modal(open?'Close cash session':'Open cash session',`<div class="form-grid">${open?field('Actual cash counted','actual_closing','number','',{min:0,step:'0.01',required:true}):field('Opening cash','opening','number',0,{min:0,step:'0.01',required:true})}</div>`,async form=>{const r=await api(open?'/cash/close':'/cash/open','POST',{...fd(form),id:open?.id});toast(open?'Expected '+rs(r.expected)+' · Variance '+rs(r.variance):'Cash session opened')},{save:open?'Close session':'Open session'})}
function drawModal(){modal('Owner drawing',`<div class="form-grid">${field('Amount','amount','number','',{min:0,step:'0.01',required:true})}${field('Notes','notes')}</div>`,async form=>{await api('/drawings','POST',fd(form));toast('Drawing recorded')},{save:'Record drawing'})}
async function reports(){if(!roleAtLeast('manager')){$('#content').innerHTML=empty('Manager access required');return}const today=new Date().toISOString().slice(0,10),from=new Date(Date.now()-30*86400000).toISOString().slice(0,10);const d=await api('/reports?from='+from+'&to='+today);const revenue=d.sales.reduce((s,r)=>s+r.revenue,0),gross=d.categories.reduce((s,r)=>s+r.gross_profit,0);$('#content').innerHTML=heading('Business intelligence','Reports','Revenue, gross margin, stock value and sales activity.',`<button class="btn" id="export-report">Export CSV</button>`)+`<div class="grid4"><div class="stat"><div class="label">Sales · 30 days</div><div class="value">${rs(revenue)}</div></div><div class="stat"><div class="label">Gross item profit</div><div class="value">${rs(gross)}</div></div><div class="stat"><div class="label">Stock at cost</div><div class="value">${rs(d.stock.accessory_cost+d.phoneStock.cost)}</div></div><div class="stat"><div class="label">Expenses</div><div class="value">${rs(d.expenses.total)}</div></div></div><div class="grid2 section"><div class="panel"><div class="panel-head"><h2>Sales by category</h2></div>${table(['Category','Units','Revenue','Gross profit'],d.categories.map(c=>`<tr><td class="main-cell">${esc(c.category)}</td><td>${c.units}</td><td>${rs(c.revenue)}</td><td>${rs(c.gross_profit)}</td></tr>`))}</div><div class="panel"><div class="panel-head"><h2>Sales by staff</h2></div>${table(['Staff','Invoices','Revenue','Discounts'],d.staff.map(s=>`<tr><td class="main-cell">${esc(s.name)}</td><td>${s.sales}</td><td>${rs(s.revenue)}</td><td>${rs(s.discounts)}</td></tr>`))}</div></div><div class="panel section"><div class="panel-head"><h2>Profit by handset</h2><span class="subtle">Price less allocated discount, purchase and preparation cost</span></div>${table(['Invoice','Phone','IMEI','Sale price','Cost','Profit'],d.phoneProfit.map(p=>`<tr><td>${esc(p.invoice_no)}</td><td class="main-cell">${esc(p.product_name)}</td><td>${esc(p.imei1)}</td><td>${rs(p.unit_price)}</td><td>${rs(p.purchase_cost+p.prep_cost)}</td><td>${rs(p.profit)}</td></tr>`))}</div><div class="panel section"><div class="panel-head"><h2>Slow moving stock</h2></div>${table(['Product','Quantity','Last sale'],d.slow.map(p=>`<tr><td class="main-cell">${esc(p.name)}</td><td>${p.quantity}</td><td>${date(p.last_sale)}</td></tr>`))}</div>`;$('#export-report').onclick=()=>{const csv=['day,invoices,revenue,discounts',...d.sales.map(s=>`${s.day},${s.count},${s.revenue},${s.discounts}`)].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='sales-report.csv';a.click();URL.revokeObjectURL(a.href)}}
async function rates(){const [rows,history,products]=await Promise.all([api('/market-rates'),roleAtLeast('manager')?api('/price-history'):Promise.resolve([]),api('/products')]);$('#content').innerHTML=heading('Price reference','Market rates','Keep buying and selling reference prices for popular models.',roleAtLeast('manager')?'<button class="btn primary" id="add-rate">＋ Update rate</button>':'')+`<div class="panel"><div class="panel-head"><h2>Current market rates</h2></div>${table(['Model','Buying rate','Selling rate','Updated'],rows.map(r=>`<tr><td class="main-cell">${esc(r.name)}</td><td>${rs(r.buy_rate)}</td><td>${rs(r.sell_rate)}</td><td>${date(r.date)}</td></tr>`))}</div>${roleAtLeast('manager')?`<div class="panel section"><div class="panel-head"><h2>Shop price history</h2></div>${table(['Date','Product','Old cost','New cost','Old price','New price'],history.map(h=>`<tr><td>${date(h.date)}</td><td class="main-cell">${esc(h.product_name)}</td><td>${rs(h.old_cost)}</td><td>${rs(h.new_cost)}</td><td>${rs(h.old_price)}</td><td>${rs(h.new_price)}</td></tr>`))}</div>`:''}`;$('#add-rate')?.addEventListener('click',()=>modal('Update market rate',`<div class="form-grid">${select('Phone model','product_id',productOpts(products,p=>p.category==='phone'))}${field('Buying rate','buy_rate','number','',{required:true,min:0,step:'0.01'})}${field('Selling rate','sell_rate','number','',{required:true,min:0,step:'0.01'})}</div>`,async f=>{await api('/market-rates','POST',fd(f));toast('Market rate updated')},{save:'Save rate'}))}
async function search(){const query=window.searchTerm||'';$('#content').innerHTML=heading('Find anything','IMEI & smart search','Trace phones from purchase to sale, or find customers and invoices.')+`<input id="search-input" class="search" style="width:100%;margin-bottom:18px" placeholder="Search IMEI, model, customer, phone, invoice or barcode" value="${esc(query)}"><div id="search-results"></div>`;const search=async()=>{const term=$('#search-input').value.trim();if(!term){$('#search-results').innerHTML=empty('Search your shop','Enter an IMEI, model, customer or invoice number.');return}const r=await api('/search?q='+encodeURIComponent(term));$('#search-results').innerHTML=`<div class="panel"><div class="panel-head"><h2>Phones · ${r.phones.length}</h2></div>${table(['IMEI','Model','PTA','Status','Purchased',''],r.phones.map(h=>`<tr><td class="main-cell">${esc(h.imei1)}</td><td>${esc(h.product_name)}</td><td>${badge(h.pta_status)}</td><td>${badge(h.status)}</td><td>${date(h.purchase_date)}</td><td><button class="btn small phone-history" data-imei="${esc(h.imei1)}">History</button></td></tr>`))}</div><div class="panel section"><div class="panel-head"><h2>Invoices · ${r.sales.length}</h2></div>${table(['Invoice','Customer','Date','Total'],r.sales.map(s=>`<tr><td class="main-cell">${esc(s.invoice_no)}</td><td>${esc(s.customer||'Walk-in')}</td><td>${date(s.date)}</td><td>${rs(s.total)}</td></tr>`))}</div><div class="panel section"><div class="panel-head"><h2>Products · ${r.products.length}</h2></div>${table(['Product','Category','Barcode','Price'],r.products.map(p=>`<tr><td class="main-cell">${esc(p.name)}</td><td>${esc(p.category)}</td><td>${esc(p.barcode||'—')}</td><td>${rs(p.price)}</td></tr>`))}</div>`;document.querySelectorAll('.phone-history').forEach(b=>b.onclick=()=>phoneHistoryModal(b.dataset.imei))};let timer;$('#search-input').oninput=()=>{clearTimeout(timer);timer=setTimeout(search,220)};if(query)search();window.searchTerm=''}
async function phoneHistoryModal(imei){const h=await api('/phone-history?imei='+encodeURIComponent(imei));modal('Phone history · '+imei,`<div class="summary-box"><span>${esc(h.phone.product_name)} · ${esc(h.phone.condition_grade||'')} · ${esc(h.phone.pta_status)}</span>${badge(h.phone.status)}</div><div class="grid2 section"><div><h3 class="form-title">Purchase</h3><p>${date(h.phone.purchase_date)}<br>${roleAtLeast('manager')?rs(h.phone.purchase_cost):''}<br>${esc(h.phone.supplier_name||'Customer trade-in / used purchase')}</p></div><div><h3 class="form-title">Sale</h3><p>${h.sale?`${esc(h.sale.invoice_no)} · ${date(h.sale.date)}<br>${esc(h.sale.customer||'Walk-in')} · ${rs(h.sale.total)}`:'Not yet sold'}</p></div></div><h3 class="form-title">Warranty claims</h3>${table(['Date','Issue','Status'],h.warranty.map(w=>`<tr><td>${date(w.date)}</td><td>${esc(w.issue)}</td><td>${badge(w.status)}</td></tr>`))}<h3 class="form-title" style="margin-top:20px">Stock history</h3>${table(['Date','Action','Change'],h.movements.map(m=>`<tr><td>${date(m.date)}</td><td>${esc(m.reason)}</td><td>${m.delta>0?'+':''}${m.delta}</td></tr>`))}`,async()=>{},{wide:true,save:'Close'});$('#modal-form').onsubmit=e=>{e.preventDefault();closeModal()}}
async function settings(){const [branches,backups,auditRows]=await Promise.all([api('/branches'),roleAtLeast('owner')?api('/backup'):Promise.resolve([]),roleAtLeast('owner')?api('/audit'):Promise.resolve([])]);$('#content').innerHTML=heading('Administration','Settings','Manage staff, branches, data backups and audit history.')+`<div class="grid2"><div class="panel"><div class="panel-head"><h2>Branches</h2>${roleAtLeast('owner')?'<button class="btn small" id="add-branch">＋ Add</button>':''}</div>${table(['Branch','Address','Phone'],branches.map(b=>`<tr><td class="main-cell">${esc(b.name)}</td><td>${esc(b.address||'—')}</td><td>${esc(b.phone||'—')}</td></tr>`))}</div><div class="panel"><div class="panel-head"><h2>Data backups</h2>${roleAtLeast('owner')?'<div class="actions"><button class="btn small" id="new-backup">Create backup</button><button class="btn small" id="restore-backup">Restore</button></div>':''}</div><p class="inline-note">Backups are stored beside your local database. Copy them to another drive regularly.</p>${backups.length?backups.map(b=>`<div class="summary-box">${esc(b)}</div>`).join(''):empty('No backups yet')}</div></div><div class="panel section"><div class="panel-head"><h2>Staff accounts</h2>${roleAtLeast('owner')?'<button class="btn small" id="add-user">＋ Add staff</button>':''}</div><div id="users-table"></div></div><div class="panel section"><div class="panel-head"><h2>Activity log</h2></div>${roleAtLeast('owner')?table(['Date','Staff','Action','Record'],auditRows.map(a=>`<tr><td>${date(a.date)}</td><td>${esc(a.user_name||'System')}</td><td>${esc(a.action)}</td><td>${esc(a.entity)} #${esc(a.entity_id||'')}</td></tr>`)):empty('Owner access required')}</div>`;if(roleAtLeast('manager')){const users=await api('/users');$('#users-table').innerHTML=table(['Name','Username','Role','Active'],users.map(u=>`<tr><td class="main-cell">${esc(u.name)}</td><td>${esc(u.username)}</td><td>${badge(u.role)}</td><td>${u.active?'Yes':'No'}</td></tr>`))}$('#add-branch')?.addEventListener('click',()=>modal('Add branch',`<div class="form-grid">${field('Branch name','name','text','',{required:true})}${field('Address','address')}${field('Phone','phone')}</div>`,async f=>{await api('/branches','POST',fd(f));toast('Branch added')}));$('#new-backup')?.addEventListener('click',async()=>{try{const b=await api('/backup','POST',{});toast('Backup created: '+b.name);render()}catch(e){toast(fmtErr(e),true)}});$('#restore-backup')?.addEventListener('click',()=>modal('Restore a backup',`<div class="alert">Restoring replaces current shop records. A safety copy of the current database is saved first.</div><div class="form-grid">${select('Backup file','name',[['','Choose backup'],...backups.map(b=>[b,b])],'',true)}${field('Type RESTORE to confirm','confirmation','text','',{required:true})}</div>`,async f=>{const d=fd(f);if(d.confirmation!=='RESTORE')throw Error('Type RESTORE exactly');await api('/restore','POST',{name:d.name});const st=await api('/status');token='';localStorage.removeItem('shop_token');user=null;toast('Backup restored. Please sign in again.');login(st.setup)},{save:'Restore backup'}));$('#add-user')?.addEventListener('click',()=>modal('Add staff account',`<div class="form-grid">${field('Full name','name','text','',{required:true})}${field('Username','username','text','',{required:true})}${field('Password (8+ characters)','password','password','',{required:true})}${select('Role','role',['manager','salesman','cashier','technician'].map(x=>[x,x]))}</div>`,async f=>{await api('/users','POST',fd(f));toast('Staff account created')}))}
const pages={dashboard,pos,inventory,purchases,sales,contacts,repairs,warranties,installments,cash,reports,rates,search,settings};
